subprocess.run(['./executable', 'raster', 'create', '--size', '12,24', 'test_f.tif'])
p_orig = subprocess.run(['./executable', 'info', '-f', 'json', 'test_f.tif'], capture_output=True, text=True)

w, h, dt = 12, 24, 'Byte'
fn = 'test_f.tif'
res = {
    'description': fn,
    'driverShortName': 'GTiff',
    'driverLongName': 'GeoTIFF',
    'files': [fn],
    'size': [w, h],
    'metadata': {'IMAGE_STRUCTURE': {'INTERLEAVE': 'BAND'}},
    'cornerCoordinates': {
        'upperLeft': [0.0, 0.0],
        'lowerLeft': [0.0, float(h)],
        'lowerRight': [float(w), float(h)],
        'upperRight': [float(w), 0.0],
        'center': [w / 2.0, h / 2.0]
    },
    'bands': [
        {
            'band': 1,
            'block': [w, h],
            'type': dt,
            'colorInterpretation': 'Gray',
            'metadata': {}
        }
    ],
    'stac': {
        'proj:shape': [h, w],
        'raster:bands': [
            {
                'data_type': 'uint8'
            }
        ],
        'eo:bands': [
            {
                'name': 'b1',
                'description': 'Gray'
            }
        ]
    }
}

p_dump = json.dumps(res, indent=2, separators=(',', ':')).replace('/', '\\/').replace('"metadata":{}', '"metadata":{\n      }') + '\n'

print('Exact match:', p_orig.stdout == p_dump)

subprocess.run(['./executable', 'dataset', 'delete', 'test_f.tif'])
""}

